#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────
# Moves the site, the invite links and the privacy and terms pages to the host in infra/cdk.json (issue #150): the
# certificate for both hosts in us-east-1, the records at SiteGround (matthewcelia.com's DNS host; checked below), the
# deploy, the checks after it, and the console fields that name the host. The old host stays for good: old invite links,
# QR codes and installed apps name it.
#
#   infra/scripts/domain-wizard.sh                  # from the start; finished stages check themselves and move on
#   WIZARD_FROM=4 infra/scripts/domain-wizard.sh    # resume at stage 4 (e.g. waiting on the certificate)
#
# It changes AWS in two places only, each after asking: it requests one certificate tagged project=birdjournal, and it runs
# infra/scripts/deploy.sh, which deploys the BirdJournal stack. Everything else it does in the shared account is read-only.
# Run it from a checkout that holds both this change and everything the live API already runs (stage 6 explains).

run_wizard() {

TOTAL_STAGES=10
WIZARD_FROM="${WIZARD_FROM:-1}"

for tool in aws jq dig curl; do
  command -v "$tool" >/dev/null 2>&1 || { printf '%s is required: brew install %s\n' "$tool" "$tool" >&2; exit 1; }
done

INFRA_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_DIR="$(cd "$INFRA_DIR/.." && pwd)"
SCRIPT="infra/scripts/domain-wizard.sh"
mkdir -p "$HOME/keys"
ENV_FILE="$HOME/keys/birdjournal.env"
CERT_REGION="us-east-1" # CloudFront only takes certificates from here
STACK_REGION="us-west-2"
export AWS_PROFILE="${AWS_PROFILE:-lsvr-admin}"
DOMAIN=$(jq -r '.context.inviteDomain' "$INFRA_DIR/cdk.json")
FORMER_HOSTS=$(jq -r '(.context.inviteFormerDomains // []) | join(" ")' "$INFRA_DIR/cdk.json")
HOSTS_JSON=$(jq -c '[.context.inviteDomain] + (.context.inviteFormerDomains // [])' "$INFRA_DIR/cdk.json")
APP_ID=$(jq -r '.context.iosAppIds[0]' "$INFRA_DIR/cdk.json")
ZONE="${DOMAIN#*.}"   # matthewcelia.com, the zone SiteGround hosts
HOST="${DOMAIN%%.*}"  # the new record's name inside it
SITEGROUND="https://my.siteground.com/websites/list"
APPLE_CDN="https://app-site-association.cdn-apple.com/a/v1"
AASA_PATH="/.well-known/apple-app-site-association"

die() { warn "$1"; [[ -z "${2:-}" ]] || warn "Fix that, then: WIZARD_FROM=$2 $SCRIPT"; exit 1; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# Fail before the browser work, not after it.
AWS_ACCOUNT=$(aws sts get-caller-identity --query Account --output text 2>/dev/null) || {
  printf 'AWS profile %s has no working credentials (aws sso login --profile %s?). Fix that, then re-run.\n' \
    "$AWS_PROFILE" "$AWS_PROFILE" >&2
  exit 1
}

# clean NAME: DNS names compare in lower case, without the final dot.
clean() { local name; name=$(printf '%s' "$1" | tr '[:upper:]' '[:lower:]'); printf '%s' "${name%.}"; }

# begin "Name" starts the next stage, or skips it (returning 1) when it comes before WIZARD_FROM.
begin() {
  if (( _STAGE_INDEX + 1 < WIZARD_FROM )); then _STAGE_INDEX=$((_STAGE_INDEX + 1)); return 1; fi
  stage "$1"
}

stack_output() {
  aws cloudformation describe-stacks --region "$STACK_REGION" --stack-name BirdJournal \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text 2>/dev/null || true
}

# cname_of NAME [SERVER]: the record's target, asking SERVER if given; empty if there's none.
cname_of() {
  local answer
  answer=$(dig +short +time=3 +tries=2 CNAME "$1" ${2:+"@$2"} 2>/dev/null | sed -n 1p || true)
  clean "$answer"
}

# find_certificate: the ARN of this project's certificate for every host, issued ones first; empty if there's none, and
# failing if ACM can't say, so call it as arn=$(find_certificate) || exit 1. The shared account holds other projects'
# certificates: one without the project's tag is left alone, whatever it covers.
find_certificate() {
  local listed status arn tagged
  listed=$(aws acm list-certificates --region "$CERT_REGION" --certificate-statuses ISSUED PENDING_VALIDATION --output json) ||
    { warn "Can't list the certificates in $CERT_REGION." >&2; return 1; }
  while read -r status arn; do
    [[ -n "$arn" ]] || continue
    tagged=$(aws acm list-tags-for-certificate --region "$CERT_REGION" --certificate-arn "$arn" \
      --query "length(Tags[?Key=='project' && Value=='birdjournal'])" --output text 2>/dev/null </dev/null || echo 0)
    if [[ "$tagged" == "1" ]]; then printf '%s' "$arn"; return 0; fi
    warn "$arn covers these hosts but isn't tagged project=birdjournal, so this wizard leaves it alone." >&2
  done < <(jq -r --arg domain "$DOMAIN" --argjson hosts "$HOSTS_JSON" '
    [.CertificateSummaryList[]
      | select(.DomainName == $domain and (($hosts - (.SubjectAlternativeNameSummaries // [])) | length == 0))]
    | sort_by(.Status) | .[] | "\(.Status) \(.CertificateArn)"' <<<"$listed")
}

certificate_status() {
  aws acm describe-certificate --region "$CERT_REGION" --certificate-arn "$1" \
    --query 'Certificate.Status' --output text 2>/dev/null || echo "UNKNOWN"
}

# siteground_name FQDN: the Name to type in SiteGround's zone editor, which appends the zone itself.
siteground_name() { local name; name=$(clean "$1"); printf '%s' "${name%."$ZONE"}"; }

# The distribution behind the stack's CNAME target, as JSON: its aliases and its certificate.
distribution() {
  aws cloudfront list-distributions --output json \
    --query "DistributionList.Items[?DomainName=='$1'] | [0].{aliases: Aliases.Items, certificate: ViewerCertificate.ACMCertificateArn}"
}

checkout() {
  printf '%s at %s' "$(git -C "$REPO_DIR" rev-parse --abbrev-ref HEAD 2>/dev/null || echo unknown)" \
    "$(git -C "$REPO_DIR" rev-parse --short HEAD 2>/dev/null || echo unknown)"
}

# probe URL: "<status>|<content type>|<redirect>", following nothing.
probe() { curl -sS -o /dev/null -w '%{http_code}|%{content_type}|%{redirect_url}' --max-time 20 "$1" 2>/dev/null || echo "000||"; }

CHECK_FAILURES=0
failed() { warn "$1"; CHECK_FAILURES=$((CHECK_FAILURES + 1)); }

# expect_page URL TEXT: 200 from the URL itself, and the page says TEXT.
expect_page() {
  local answer body; answer=$(probe "$1"); body=$(curl -sS --max-time 20 "$1" 2>/dev/null || true)
  if [[ "${answer%%|*}" == "200" && "$body" == *"$2"* ]]; then ok "$1"
  else failed "$1 answered $answer, wanted 200 and a page saying \"$2\"."; fi
}

# expect_association HOST: the file itself with no redirect (Apple doesn't follow one), as JSON, naming the app.
expect_association() {
  local url="https://$1$AASA_PATH" answer status type rest location
  answer=$(probe "$url"); status="${answer%%|*}"; rest="${answer#*|}"; type="${rest%%|*}"; location="${rest#*|}"
  if [[ "$status" == "200" && -z "$location" && "$type" == application/json* ]] &&
    curl -sS --max-time 20 "$url" 2>/dev/null | jq -e --arg app "$APP_ID" \
      '.applinks.details[0] | (.appIDs | index($app)) != null and (.components[0]["/"] == "/i/*")' >/dev/null 2>&1; then
    ok "$url: 200, $type, no redirect, names the app"
  else
    failed "$url answered $answer, wanted 200, application/json, no redirect and the app's ID."
  fi
}

# expect_redirect FROM TO: a permanent redirect from one URL to exactly the other.
expect_redirect() {
  local answer status rest location
  answer=$(probe "$1"); status="${answer%%|*}"; rest="${answer#*|}"; location="${rest#*|}"
  if [[ "$status" == "301" && "$location" == "$2" ]]; then ok "$1 → $2"
  else failed "$1 answered $answer, wanted 301 to $2."; fi
}

# DNS is read before anything else, because every SiteGround step below depends on it.
NAME_SERVERS=$(dig +short NS "$ZONE" 2>/dev/null | tr '[:upper:]' '[:lower:]' || true)
AUTH_NS=$(clean "$(printf '%s\n' "$NAME_SERVERS" | sed -n 1p)")

banner "Featherguild: the site moves to $DOMAIN"

if begin "Where things stand (read-only)"; then
  say "Account $AWS_ACCOUNT, profile $AWS_PROFILE. Nothing changes in this stage."
  [[ "$NAME_SERVERS" == *siteground* ]] ||
    die "$ZONE's name servers aren't SiteGround's ('$NAME_SERVERS'). This wizard's DNS steps are for SiteGround: stop and rework them."
  ok "$ZONE's DNS is at SiteGround ($AUTH_NS)"
  status=$(aws cloudformation describe-stacks --region "$STACK_REGION" --stack-name BirdJournal \
    --query 'Stacks[0].StackStatus' --output text 2>/dev/null || echo "MISSING")
  case "$status" in
    *_IN_PROGRESS) die "The stack is $status: someone is deploying. Wait for it, then re-run." ;;
    MISSING) warn "There's no BirdJournal stack yet. Stage 5 will tell you when to deploy it." ;;
    *) ok "Stack BirdJournal: $status" ;;
  esac
  target=$(clean "$(stack_output InviteDistributionDomain)")
  for former in $FORMER_HOSTS; do
    if [[ -n "$target" && "$(cname_of "$former")" == "$target" ]]; then ok "$former → $target (it stays)"
    else warn "$former doesn't point at the stack's distribution ($target). Stage 5 checks this again."; fi
  done
  note "Checkout: $(checkout)"
  pause
fi

if begin "AWS Certificate Manager: one certificate for both hosts"; then
  say "CloudFront answers on every host with one certificate from $CERT_REGION, so it has to name them all:"
  note "$(jq -r 'join(", ")' <<<"$HOSTS_JSON")"
  arn=$(find_certificate) || exit 1
  if [[ -n "$arn" ]]; then
    ok "Found it: $arn ($(certificate_status "$arn"))"
  elif confirm "Request a certificate for these hosts in $CERT_REGION, tagged project=birdjournal?"; then
    # shellcheck disable=SC2086 # the former hosts are one word each
    arn=$(aws acm request-certificate --region "$CERT_REGION" --domain-name "$DOMAIN" \
      --subject-alternative-names $FORMER_HOSTS --validation-method DNS --idempotency-token birdjournalfeatherguild \
      --tags Key=project,Value=birdjournal --query CertificateArn --output text) || die "ACM refused the request." 2
    ok "Requested: $arn"
  else
    die "Nothing to do without a certificate; re-run when ready."
  fi
  note "INVITE_CERTIFICATE_ARN stays on the current certificate until this one is issued (stage 4)."
  pause
fi

if begin "SiteGround: the certificate's validation records"; then
  arn=$(find_certificate) || exit 1
  [[ -n "$arn" ]] || die "No certificate for these hosts yet." 2
  say "ACM proves each host is yours by looking up one CNAME record per host. It may reuse the record already there."
  records=""
  for _ in $(seq 1 30); do
    records=$(aws acm describe-certificate --region "$CERT_REGION" --certificate-arn "$arn" --output json \
      | jq -r '.Certificate.DomainValidationOptions[] | "\(.DomainName) \(.ResourceRecord.Name // "") \(.ResourceRecord.Value // "")"' || true)
    [[ -n "$records" ]] && ! grep -qE '^[^ ]+ +$' <<<"$records" && break
    sleep 2 # ACM takes a few seconds to publish the records after the request
  done
  if [[ -z "$records" ]] || grep -qE '^[^ ]+ +$' <<<"$records"; then
    die "ACM hasn't published the records yet." 3
  fi
  to_add=0
  while read -r name record value; do
    if [[ "$(cname_of "$record" "$AUTH_NS")" == "$(clean "$value")" ]]; then
      ok "$name: its record is already at SiteGround"
    else
      if (( to_add == 0 )); then
        open_url "$SITEGROUND"
        step "Websites → the site for $ZONE → Site Tools → Domain → DNS Zone Editor → $ZONE → CNAME tab."
      fi
      to_add=$((to_add + 1))
      say ""
      say "$name:"
      step "Name: $(siteground_name "$record")"
      note "  (SiteGround adds .$ZONE itself; the full name is $(clean "$record"))"
      step "Resolves to: $(clean "$value")"
      step "TTL: leave the default → Create."
    fi
  done <<<"$records"
  note "Keep these records for good: ACM renews the certificate each year by looking them up again."
  if (( to_add )); then pause "Press Enter once you've created the record(s)."; else pause; fi
fi

if begin "Wait for the certificate, and save it"; then
  arn=$(find_certificate) || exit 1
  [[ -n "$arn" ]] || die "No certificate for these hosts yet." 2
  say "ACM checks the records every few minutes; it usually issues within 5 to 30 minutes."
  status=$(certificate_status "$arn")
  waited=0
  while [[ "$status" == "PENDING_VALIDATION" ]] && (( waited < 1800 )); do
    printf '\r  %s%s, waited %d min%s ' "$DIM" "$status" $((waited / 60)) "$RESET"
    sleep 30; waited=$((waited + 30))
    status=$(certificate_status "$arn")
  done
  printf '\n'
  case "$status" in
    ISSUED) ok "Issued: $arn" ;;
    PENDING_VALIDATION) die "Still pending after 30 minutes. Compare the records at SiteGround with stage 3's." 3 ;;
    *) die "The certificate is $status. Look at it in the ACM console ($CERT_REGION), and delete it there if it failed." 2 ;;
  esac
  write_env INVITE_CERTIFICATE_ARN "$arn"
  note "The old certificate stays in ACM, unused; nothing here deletes it."
  pause
fi

if begin "SiteGround: point $DOMAIN at CloudFront"; then
  target=$(clean "$(stack_output InviteDistributionDomain)")
  if [[ -z "$target" || "$target" == "none" ]]; then
    die "The stack has no InviteDistributionDomain output. On a new account: infra/scripts/deploy.sh, then come back." 5
  fi
  others=$(aws cloudfront list-distributions --output text \
    --query "DistributionList.Items[?Aliases.Items && contains(Aliases.Items, '$DOMAIN') && DomainName!='$target'].Id" || true)
  [[ -z "$others" || "$others" == "None" ]] || die "Another distribution ($others) already answers on $DOMAIN. Leave it alone and find out why."
  current=$(cname_of "$DOMAIN" "$AUTH_NS")
  if [[ "$current" == "$target" ]]; then
    ok "$DOMAIN → $target already"
  elif [[ -n "$current" ]]; then
    die "$DOMAIN already points at $current. This wizard doesn't overwrite a record it didn't make." 5
  else
    say "The distribution keeps its address, so the record goes in before the deploy: invite links work the"
    say "moment the API starts making them. Until the deploy this host answers with an error, and nothing links to it yet."
    open_url "$SITEGROUND"
    step "Site Tools → Domain → DNS Zone Editor → $ZONE → CNAME tab."
    step "Name: $HOST"
    step "Resolves to: $target"
    step "TTL: leave the default → Create."
    pause "Press Enter once the record is created."
    for _ in $(seq 1 40); do
      current=$(cname_of "$DOMAIN" "$AUTH_NS")
      [[ "$current" == "$target" ]] && break
      sleep 15
    done
    [[ "$current" == "$target" ]] || die "SiteGround's name server says $DOMAIN → '$current', wanted $target." 5
    ok "$DOMAIN → $target"
  fi
  for former in $FORMER_HOSTS; do
    [[ "$(cname_of "$former" "$AUTH_NS")" == "$target" ]] ||
      die "$former no longer points at $target. Old links depend on that record: put it back." 5
    ok "$former → $target (keep this record for good)"
  done
  pause
fi

if begin "Deploy"; then
  INVITE_CERTIFICATE_ARN="${INVITE_CERTIFICATE_ARN:-$(_existing INVITE_CERTIFICATE_ARN || true)}"
  export INVITE_CERTIFICATE_ARN
  "$INFRA_DIR/scripts/check-invite-certificate.sh" || die "The saved certificate won't do." 4

  target=$(clean "$(stack_output InviteDistributionDomain)")
  live=$(distribution "$target" 2>/dev/null || echo '{}')
  if jq -e --argjson hosts "$HOSTS_JSON" --arg arn "$INVITE_CERTIFICATE_ARN" \
      '(($hosts - (.aliases // [])) | length == 0) and .certificate == $arn' >/dev/null 2>&1 <<<"$live" &&
    [[ "$(stack_output InviteBaseUrl)" == "https://$DOMAIN" ]]; then
    ok "Already deployed: the distribution answers on every host with this certificate, and the API uses $DOMAIN."
    deploy_now=no
    if confirm "Deploy again anyway?"; then deploy_now=yes; fi
  else
    say "This deploys whatever this checkout holds, and the live API is replaced by this checkout's backend."
    note "Checkout: $(checkout)"
    # Slice 8's backend (#150) went live from its own branch. A checkout without it would take its fields back off the API.
    if ! grep -q "class GoalSpecies" "$REPO_DIR/backend/src/birdjournal_api/goals_api.py"; then
      warn "This checkout lacks the Guild-data backend (#150, slice 8) that's already live: goals' species would"
      warn "disappear from the API. Merge it here first, or deploy from the branch that has both."
      confirm "Deploy anyway?" || die "Stopped before the deploy." 6
    fi
    dirty=$(git -C "$REPO_DIR" status --porcelain -- infra backend 2>/dev/null || true)
    if [[ -n "$dirty" ]]; then
      warn "infra/ or backend/ has uncommitted changes, and they would deploy too:"
      note "$dirty"
      confirm "Deploy them?" || die "Stopped before the deploy." 6
    fi
    if confirm "See what would change first (cdk diff, reads AWS only, about 2 minutes)?"; then
      "$INFRA_DIR/scripts/deploy.sh" --diff || die "cdk diff failed." 6
      say "Expect: the distribution's aliases and certificate, the viewer function, the API's INVITE_BASE_URL and"
      say "code, and the site's files. Anything else, stop and ask."
    fi
    deploy_now=no
    if confirm "Deploy BirdJournal to $AWS_ACCOUNT / $STACK_REGION now?"; then deploy_now=yes; fi
  fi
  if [[ "$deploy_now" == "yes" ]]; then
    note "CloudFront takes 5 to 15 minutes. cdk asks once more if IAM permissions widen."
    "$INFRA_DIR/scripts/deploy.sh" || die "The deploy failed. If CloudFormation had started, it rolls back by itself and the old host keeps working." 6
    ok "Deployed."
  elif [[ "$(stack_output InviteBaseUrl)" != "https://$DOMAIN" ]]; then
    SKIPPED+=("the deploy: WIZARD_FROM=6 $SCRIPT")
    finish; exit 0
  fi
  pause
fi

if begin "Check the site on both hosts"; then
  say "Waiting for $DOMAIN to resolve here."
  for _ in $(seq 1 40); do
    [[ -n "$(dig +short "$DOMAIN" 2>/dev/null || true)" ]] && break
    sleep 15
  done
  expect_page "https://$DOMAIN/" "Featherguild"
  expect_page "https://$DOMAIN/privacy" "Privacy policy"
  expect_page "https://$DOMAIN/terms" "Terms of use"
  expect_page "https://$DOMAIN/i/wizard-check" "invited to a Guild"
  expect_association "$DOMAIN"
  for former in $FORMER_HOSTS; do
    expect_association "$former"
    expect_redirect "https://$former/i/wizard-check" "https://$DOMAIN/i/wizard-check"
    expect_redirect "https://$former/privacy" "https://$DOMAIN/privacy"
    expect_redirect "https://$former/terms" "https://$DOMAIN/terms"
    expect_redirect "https://$former/" "https://$DOMAIN/"
  done
  if (( CHECK_FAILURES )); then
    die "$CHECK_FAILURES check(s) failed. DNS or CloudFront may still be settling: give it a few minutes." 7
  fi
  say ""
  say "Apple's CDN holds its own copy of the file, and phones read that one. It can lag by a day or more, so this"
  say "is for information only:"
  for host in $DOMAIN $FORMER_HOSTS; do
    note "  $APPLE_CDN/$host: $(curl -sS -o /dev/null -w '%{http_code}' --max-time 20 "$APPLE_CDN/$host" 2>/dev/null || echo unreachable)"
  done
  pause
fi

if begin "Check the API's invite links"; then
  base=$(stack_output InviteBaseUrl)
  [[ "$base" == "https://$DOMAIN" ]] || die "The stack's InviteBaseUrl is $base, wanted https://$DOMAIN. Has it deployed?" 6
  function_name=$(aws cloudformation list-stack-resources --region "$STACK_REGION" --stack-name BirdJournal --output text \
    --query "StackResourceSummaries[?ResourceType=='AWS::Lambda::Function' && starts_with(LogicalResourceId, 'ApiFunction')].PhysicalResourceId | [0]")
  live_base=$(aws lambda get-function-configuration --region "$STACK_REGION" --function-name "$function_name" \
    --query 'Environment.Variables.INVITE_BASE_URL' --output text)
  [[ "$live_base" == "https://$DOMAIN" ]] || die "The API's INVITE_BASE_URL is $live_base, wanted https://$DOMAIN." 6
  ok "The API makes links on https://$DOMAIN"
  say "Only a signed-in app can ask for a real one. On your phone, in a build with Guilds (a Debug build today):"
  step "Guilds → a Guild → Invite → Copy link. Send it to this Mac and paste it below, or press Enter to skip."
  ask INVITE_LINK_CHECK "Invite link:"
  if [[ -z "$INVITE_LINK_CHECK" ]]; then
    SKIPPED+=("a real invite link from the app: WIZARD_FROM=8 $SCRIPT")
  else
    [[ "$INVITE_LINK_CHECK" == "https://$DOMAIN/i/"* ]] || die "That link isn't on $DOMAIN: $INVITE_LINK_CHECK" 8
    expect_page "$INVITE_LINK_CHECK" "invited to a Guild"
    for former in $FORMER_HOSTS; do
      expect_redirect "https://$former/i/${INVITE_LINK_CHECK##*/}" "$INVITE_LINK_CHECK"
    done
    (( CHECK_FAILURES == 0 )) || die "The link doesn't work yet." 8
  fi
  pause
fi

if begin "App Store Connect: the addresses it lists"; then
  say "New addresses: https://$DOMAIN/privacy, https://$DOMAIN/terms, and https://$DOMAIN/ for support."
  open_url "https://appstoreconnect.apple.com/apps"
  step "App Privacy → Privacy Policy URL → https://$DOMAIN/privacy"
  step "TestFlight → Test Information → Privacy Policy URL and Marketing URL, wherever they name the old host."
  step "The version you're preparing → Support URL → https://$DOMAIN/ (and Marketing URL, if set)."
  step "General → App Information → License Agreement, if you wrote your own and it names the old host."
  note "A field that's empty or doesn't name the old host: leave it. One you can't edit until the next version: change"
  note "it then; the old address redirects in the meantime."
  if confirm "Does App Store Connect name $DOMAIN everywhere it named the old host?"; then ok "App Store Connect"
  else SKIPPED+=("App Store Connect's privacy, support and marketing URLs: WIZARD_FROM=9 $SCRIPT"); fi
  pause
fi

if begin "The other places that could name the host"; then
  website=$(aws sesv2 get-account --region "$STACK_REGION" --query 'Details.WebsiteURL' --output text 2>/dev/null || echo unknown)
  named_old=no
  for former in $FORMER_HOSTS; do [[ "$website" == *"$former"* ]] && named_old=yes; done
  if [[ "$named_old" == "yes" ]]; then
    warn "SES's account details name the old host ($website). They belong to the whole shared account: ask its owner."
    SKIPPED+=("SES's account website, $website: ask the shared account's owner")
  else
    ok "SES's production access names $website: nothing to do"
  fi
  say ""
  say "Wearables Developer Center (the app's iOS integration):"
  open_url "https://wearables.developer.meta.com/"
  step "If its Universal link or any URL it lists names the old host, change it to $DOMAIN."
  note "The repo set up the custom scheme birdjournal:// there and no https link, so there's probably nothing."
  say ""
  say "Google (only the sign-in consent screen shows these):"
  project=$(_existing GOOGLE_CLOUD_PROJECT || true)
  [[ -z "$project" ]] || open_url "https://console.cloud.google.com/auth/branding?project=$project"
  step "Branding → App home page, Privacy policy and Terms of service links: change any that name the old host."
  note "The accounts wizard only added amazoncognito.com there. Apple's Services ID and Cognito's callbacks don't use this host."
  if confirm "Do both name $DOMAIN wherever they named the old host?"; then ok "Developer Center and Google"
  else SKIPPED+=("Wearables Developer Center and Google's Branding page: WIZARD_FROM=10 $SCRIPT"); fi
  pause
fi

finish
say "Keep, for good:"
note "  the $FORMER_HOSTS CNAME and both validation records at SiteGround, and the old host in inviteFormerDomains."
say ""
say "From here on, deploy only from branches that hold this change. An older branch would take $DOMAIN back off the"
say "distribution and send the API's invite links back to the old host."
say ""
say "The order for the app: this deploy first, then the app's release. A build with the new host needs it live:"
note "  its Settings links open $DOMAIN, and a phone reads the association file when it installs the app."
say ""
say "Old apps: Release builds (TestFlight) have never had Guilds or the associated domain, which are Debug only, so"
note "  their only use of the host is Settings' privacy and terms links, and those redirect. A Debug build from before"
note "  this change opens only the old host: it can't open the new links the API makes now, and they land on the invite"
note "  page, which has no TestFlight or App Store link to follow. Build and install a new Debug build."
say ""
say "On a phone, with a new Debug build: open a new invite link and an old one from Messages. Both should open the"
say "join screen. Apple's CDN can take a day or more to pick up $DOMAIN, and a phone reads it at install."
printf '\n'
}

run_wizard "$@"; exit
